package main

import "fmt"

// takes a COPY of the array — mutations stay local
func tryMutate(arr [3]int) {
	arr[0] = 999
}

// takes a POINTER — mutations affect the caller's array
func mutate(arr *[3]int) {
	arr[0] = 999 // shorthand for (*arr)[0]
}

func main() {
	original := [3]int{1, 2, 3}

	copy := original // COPY: independent array
	copy[0] = 100
	fmt.Println("original:", original) // [1 2 3] — unchanged
	fmt.Println("copy:    ", copy)      // [100 2 3]

	tryMutate(original)
	fmt.Println("after tryMutate:", original) // [1 2 3] — still unchanged

	mutate(&original)
	fmt.Println("after mutate:   ", original) // [999 2 3] — changed via pointer
}

package main

import "fmt"

func main() {
	// arrays of a comparable element type can be compared with ==
	x := [3]int{1, 2, 3}
	y := [3]int{1, 2, 3}
	z := [3]int{1, 2, 9}
	fmt.Println("x == y:", x == y) // true (same length AND elements)
	fmt.Println("x == z:", x == z) // false

	// because arrays are comparable, they can be MAP KEYS
	gridNames := map[[2]int]string{
		{0, 0}: "origin",
		{1, 2}: "target",
	}
	fmt.Println(gridNames[[2]int{1, 2}]) // target

	// multidimensional array: 2 rows x 3 cols, row-major contiguous
	var grid [2][3]int
	grid[0] = [3]int{1, 2, 3}
	grid[1][2] = 99
	for i := range grid {
		for j := range grid[i] {
			fmt.Printf("%d ", grid[i][j])
		}
		fmt.Println()
	}
}

package main

import "fmt"

func main() {
	data := [...]int{10, 20, 30, 40} // [4]int

	sum := 0
	for i, v := range data { // v is a COPY of each element
		sum += v
		_ = i
	}
	fmt.Println("sum:", sum)        // 100
	fmt.Println("len:", len(data))  // 4 (compile-time constant)

	// range gives copies, so mutating v does NOT change the array
	for _, v := range data {
		v *= 2 // no effect on data
	}
	fmt.Println("unchanged:", data) // [10 20 30 40]

	// to mutate in place, index by position
	for i := range data {
		data[i] *= 2
	}
	fmt.Println("doubled:", data)   // [20 40 60 80]

	// slice the array to get a reference-like view over the SAME memory
	s := data[1:3]                  // []int{40, 60}, backed by data
	s[0] = 0                        // mutates data[1] too
	fmt.Println("after slice write:", data) // [20 0 60 80]
}
